import multer from 'multer';
import { randomUUID } from 'node:crypto';
const upload = multer({
  storage: multer.diskStorage({ destination: '/private-uploads', filename: (_req, file, cb) => cb(null, randomUUID()) }),
  limits: { fileSize: 2 * 1024 * 1024, files: 1 }
});
app.post('/api/documents', upload.single('document'), (req, res) => {
  res.status(201).json({ received: Boolean(req.file) });
});
